schema_ddl:
CREATE TABLE soggetti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ragione_sociale TEXT NOT NULL,
    codice_fiscale TEXT UNIQUE,
    tipo_soggetto TEXT NOT NULL CHECK (tipo_soggetto IN ('cliente', 'fornitore', 'dipendente')),
    email_contatto TEXT,
    creato_il TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE clienti (
    id INT PRIMARY KEY REFERENCES soggetti(id) ON DELETE CASCADE,
    limite_credito NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (limite_credito >= 0),
    sconto_percentuale NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (sconto_percentuale BETWEEN 0 AND 100),
    data_primo_ordine DATE
);

CREATE TABLE fornitori (
    id INT PRIMARY KEY REFERENCES soggetti(id) ON DELETE CASCADE,
    partita_iva TEXT NOT NULL UNIQUE,
    termine_pagamento_giorni INT NOT NULL DEFAULT 30 CHECK (termine_pagamento_giorni >= 0),
    punteggio_qualita NUMERIC(3,1) CHECK (punteggio_qualita BETWEEN 0 AND 10)
);

CREATE TABLE dipendenti (
    id INT PRIMARY KEY REFERENCES soggetti(id) ON DELETE CASCADE,
    matricola TEXT NOT NULL UNIQUE,
    data_assunzione DATE NOT NULL,
    stipendio_mensile NUMERIC(10,2) NOT NULL CHECK (stipendio_mensile > 0)
);
